import{_ as t,o,c as r,a2 as s}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"Mcp","description":"Mcp reference documentation","frontmatter":{"title":"Mcp","description":"Mcp reference documentation"},"headers":[],"relativePath":"knowledge/mcp.md","filePath":"knowledge/mcp.md","lastUpdated":1784485118000}'),a={name:"knowledge/mcp.md"};function i(n,e,l,c,d,p){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="mcp" tabindex="-1">Mcp <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;Mcp&quot;">​</a></h1><h1 id="model-context-protocol-mcp-—-knowledge-base" tabindex="-1">Model Context Protocol (MCP) — Knowledge Base <a class="header-anchor" href="#model-context-protocol-mcp-—-knowledge-base" aria-label="Permalink to &quot;Model Context Protocol (MCP) — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Model Context Protocol (MCP) is an open protocol that standardizes how AI applications connect to external data sources and tools. It provides a universal interface for LLMs to access context, execute tools, and interact with external systems through a client-server architecture.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><p><strong>MCP Host</strong> — The AI application that initiates connections (e.g., OpenCode, Claude Desktop, custom AI apps).</p><p><strong>MCP Client</strong> — Protocol client within the host that maintains 1:1 connections with MCP servers.</p><p><strong>MCP Server</strong> — Lightweight program that exposes specific capabilities (tools, resources, prompts) to clients.</p><p><strong>Communication flow:</strong> Host → Client → Transport → Server → External system</p><h3 id="protocol-primitives" tabindex="-1">Protocol Primitives <a class="header-anchor" href="#protocol-primitives" aria-label="Permalink to &quot;Protocol Primitives&quot;">​</a></h3><p><strong>Tools</strong> — Functions that the LLM can invoke to perform actions or retrieve data. Defined with JSON Schema parameters.</p><ul><li>Example: <code>search_docs(query: string)</code>, <code>create_issue(title: string, body: string)</code></li></ul><p><strong>Resources</strong> — Data that the server exposes for reading. URI-based, similar to GET endpoints.</p><ul><li>Example: <code>file:///path/to/doc</code>, <code>db://table/rows</code></li></ul><p><strong>Prompts</strong> — Reusable prompt templates that the server provides. Structured templates with arguments.</p><ul><li>Example: <code>code_review(language: string, file_path: string)</code></li></ul><h3 id="transports" tabindex="-1">Transports <a class="header-anchor" href="#transports" aria-label="Permalink to &quot;Transports&quot;">​</a></h3><p><strong>stdio</strong> — Standard input/output transport for local processes. Server runs as a subprocess.</p><p><strong>SSE (Server-Sent Events)</strong> — HTTP-based transport for remote servers. Server sends events, client sends messages via HTTP POST.</p><p><strong>Streamable HTTP</strong> — Newer HTTP transport supporting bidirectional streaming. Preferred for new implementations.</p><h3 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h3><ol><li><strong>Initialize</strong> — Client sends <code>initialize</code> with protocol version and capabilities</li><li><strong>Capability negotiation</strong> — Server responds with its supported capabilities</li><li><strong>Operation</strong> — Client and server exchange messages using agreed capabilities</li><li><strong>Shutdown</strong> — Clean disconnection with <code>shutdown</code> and <code>close</code></li></ol><h3 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h3><p><strong>Tool consent</strong> — Users should approve tool execution before it happens. MCP hosts should implement confirmation dialogs.</p><p><strong>Data privacy</strong> — Servers should not send sensitive data without user consent. Clients should handle data securely.</p><p><strong>Access control</strong> — Servers should implement appropriate authentication and authorization for the systems they access.</p><p><strong>Transport security</strong> — Remote transports should use TLS/HTTPS. Local stdio transport inherits process security.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Design focused servers</strong> — Each MCP server should do one thing well; separate documentation search, issue creation, and database access into different servers</li><li><strong>Define clear tool schemas</strong> — Use descriptive names, detailed descriptions, and strict JSON Schema for all tool parameters; LLMs rely on these to choose tools</li><li><strong>Implement error handling gracefully</strong> — Return meaningful error messages from tools; LLMs can use error information to adjust their approach</li><li><strong>Add user confirmation for destructive operations</strong> — Tools that modify data (create, update, delete) should require user confirmation before execution</li><li><strong>Use structured resource URIs</strong> — Design intuitive URI schemes for resources; <code>file://</code>, <code>db://</code>, <code>api://</code> prefixes clarify data source</li><li><strong>Version your protocol</strong> — Support multiple protocol versions for backward compatibility; version in capability negotiation</li><li><strong>Implement rate limiting</strong> — Prevent abuse of tools and resources; set per-tool and per-session limits</li><li><strong>Log tool invocations</strong> — Track which tools are called, with what parameters, and what results; essential for debugging and auditing</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Exposing raw database access</strong> — MCP tools should be high-level operations, not raw SQL queries; implement business logic in tools</li><li><strong>Returning unfiltered data</strong> — Resources should respect access control; don&#39;t expose data the user shouldn&#39;t see</li><li><strong>Missing error handling</strong> — Tools that crash or return cryptic errors confuse the LLM; handle all errors and return informative messages</li><li><strong>Ignoring transport security</strong> — Never transmit sensitive data over unencrypted channels; always use TLS for remote transports</li><li><strong>Hardcoding credentials</strong> — API keys and tokens should be provided by the host environment, not embedded in server code</li><li><strong>Overly broad tools</strong> — A single tool that does everything is hard for LLMs to use correctly; break into focused, specific tools</li><li><strong>Not implementing tool timeouts</strong> — Long-running tools block the conversation; implement timeouts and support cancellation</li><li><strong>Skipping capability negotiation</strong> — Always negotiate capabilities during initialization; don&#39;t assume server features</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not providing tool descriptions</strong> — LLMs choose tools based on descriptions; missing or vague descriptions lead to incorrect tool selection</li><li><strong>Ignoring parameter validation</strong> — Validate all tool inputs server-side; LLMs can generate malformed parameters</li><li><strong>Returning massive payloads</strong> — Large resource contents overwhelm the LLM context window; paginate or summarize large data</li><li><strong>Not handling concurrent tool calls</strong> — LLMs may request multiple tools simultaneously; server must handle concurrent execution</li><li><strong>Forgetting about idempotency</strong> — Tool calls may be retried; ensure repeated calls produce the same result for read operations</li><li><strong>Missing resource change notifications</strong> — When resources change, notify clients with <code>notifications/resources/updated</code></li><li><strong>Not implementing progress reporting</strong> — Long-running tools should report progress; use <code>notifications/progress</code> to keep users informed</li><li><strong>Using stdio for remote servers</strong> — stdio is designed for local processes; use HTTP-based transports for remote access</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Transport</th><th>Tool Design</th></tr></thead><tbody><tr><td>Local CLI tool</td><td>stdio</td><td>Single-purpose tools with clear parameters</td></tr><tr><td>Remote API integration</td><td>Streamable HTTP</td><td>High-level operations, rate-limited</td></tr><tr><td>Database access</td><td>stdio or HTTP</td><td>Read-only resources, parameterized queries</td></tr><tr><td>File system access</td><td>stdio</td><td>Scoped to specific directories, read/write tools</td></tr><tr><td>Real-time data</td><td>HTTP + SSE</td><td>Resources with change notifications</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Tool Type</th><th>Confirmation Required</th><th>Timeout</th></tr></thead><tbody><tr><td>Read/search</td><td>No</td><td>5-30 seconds</td></tr><tr><td>Create/update</td><td>Yes (or auto-confirm with warning)</td><td>10-60 seconds</td></tr><tr><td>Delete/destructive</td><td>Always</td><td>10-60 seconds</td></tr><tr><td>External API call</td><td>Depends on action</td><td>30-120 seconds</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>MCP Specification: <a href="https://spec.modelcontextprotocol.io/" target="_blank" rel="noreferrer">https://spec.modelcontextprotocol.io/</a></li><li>MCP GitHub Organization: <a href="https://github.com/modelcontextprotocol" target="_blank" rel="noreferrer">https://github.com/modelcontextprotocol</a></li><li>MCP TypeScript SDK: <a href="https://github.com/modelcontextprotocol/typescript-sdk" target="_blank" rel="noreferrer">https://github.com/modelcontextprotocol/typescript-sdk</a></li><li>MCP Servers Repository: <a href="https://github.com/modelcontextprotocol/servers" target="_blank" rel="noreferrer">https://github.com/modelcontextprotocol/servers</a></li><li>Anthropic MCP Documentation: <a href="https://docs.anthropic.com/en/docs/agents-and-tools/mcp" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/agents-and-tools/mcp</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Building MCP servers:</strong> Use the TypeScript or Python SDK; start with stdio transport for local development, add HTTP for remote deployment</li><li><strong>Testing:</strong> Use the MCP Inspector tool to test servers interactively; verify tool schemas and resource access</li><li><strong>Integration with OpenCode:</strong> MCP servers are configured in opencode.json under the <code>mcp</code> section; specify command, args, and environment</li><li><strong>Deployment:</strong> Package MCP servers as npm packages or Docker containers; distribute through standard package managers</li><li><strong>Arabic content:</strong> MCP tools handling Arabic text should document encoding requirements and RTL support</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',43)])])}const u=t(a,[["render",i]]);export{g as __pageData,u as default};
